DECLARE @i INT = 11;
WHILE @i <= 20
BEGIN
    DECLARE @tenBan NVARCHAR(50) = N'Bàn ' + CAST(@i AS NVARCHAR(10));
    IF NOT EXISTS (SELECT * FROM dbo.BanAn WHERE TenBan = @tenBan)
    BEGIN
        INSERT INTO dbo.BanAn (TenBan, TrangThai) 
        VALUES (@tenBan, N'Trống');
    END
    SET @i = @i + 1;
END

PRINT N'Đã thêm bàn thành công!';
GO

